      "svg": "<svg viewBox=\"0 0 1100 1100\" xmlns=\"http://www.w3.org/2000/svg\"><rect width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"40\" y=\"90\" fill=\"#ffffff\" font-family=\"sans-serif\" font-size=\"34\" font-weight=\"bold\">Two Systems, One Job</text><ellipse cx=\"350\" cy=\"450\" rx=\"170\" ry=\"140\" fill=\"#8b5cf6\" opacity=\"0.85\"/><text x=\"270\" y=\"440\" fill=\"#ffffff\" font-family=\"sans-serif\" font-size=\"30\">Lungs</text><text x=\"230\" y=\"490\" fill=\"#ffffff\" font-family=\"sans-serif\" font-size=\"22\">load oxygen</text><circle cx=\"780\" cy=\"450\" r=\"140\" fill=\"#ef4444\"/><text x=\"720\" y=\"440\" fill=\"#ffffff\" font-family=\"sans-serif\" font-size=\"30\">Heart</text><text x=\"690\" y=\"490\" fill=\"#ffffff\" font-family=\"sans-serif\" font-size=\"22\">delivers it</text><path d=\"M520 450 L640 450\" stroke=\"#10b981\" stroke-width=\"16\"/><polygon points=\"640,430 640,470 680,450\" fill=\"#10b981\"/><text x=\"40\" y=\"800\" fill=\"#888888\" font-family=\"sans-serif\" font-size=\"26\">Loading plus pumping equals oxygen everywhere.</text></svg>",
